static inline const uint8_t* q35_tensor_data(const GgufTensor* t) {
    if (q35_g_tensor_live) {
        size_t idx = (size_t)(t - q35_g_gguf.tensors);
        const uint8_t* live = q35_g_tensor_live[idx];
        if (live) return live;
    }
    return g_st.mmap_base + t->offset;
}

static inline const block_q4_K* q35_q4k_row_ptr(const GgufTensor* t, int K, int r) {
    int blocks_per_row = K / 256;
    return (const block_q4_K*)q35_tensor_data(t)
         + (size_t)r * blocks_per_row;
}
static inline const block_q5_K* q35_q5k_row_ptr(const GgufTensor* t, int K, int r) {
    int blocks_per_row = K / 256;
    return (const block_q5_K*)q35_tensor_data(t)
         + (size_t)r * blocks_per_row;
}
static inline const block_q6_K* q35_q6k_row_ptr(const GgufTensor* t, int K, int r) {
    int blocks_per_row = K / 256;
    return (const block_q6_K*)q35_tensor_data(t)
         + (size_t)r * blocks_per_row;
}
static inline const float* q35_f32_tensor_ptr(const GgufTensor* t) {
    return (const float*)q35_tensor_data(t);
}

static inline const block_q2_K* q35_q2k_row_ptr(const GgufTensor* t, int K, int r) {
    int blocks_per_row = K / 256;
    return (const block_q2_K*)q35_tensor_data(t)
         + (size_t)r * blocks_per_row;
}

/* ======================================================================
 * §2 — Q2K nibble layout (V55)
 * ----------------------------------------------------------------------
 * Byte re-arrangement of the Q2_K weight stream (values unchanged, type 42)
 * that halves NEON unpack instructions. Loaded from a sidecar file or an
 * embedded type-42 GGUF; verified against the original layout before use.
 * ====================================================================== */

/* V55: Q2K nibble-layout sidecar (offline converter, values unchanged).
 * 148B/block = scales[16]+qs[128]+d+dmin; qs = 每 32 权重 16B (低4bit=前16, 高=后16). */
static const uint8_t* q35_g_q2k_nib_base = NULL;
static int64_t*       q35_g_q2k_nib_off = NULL;   /* per-GGUF-tensor: sidecar off or -1 */
static uint32_t       q35_g_q2k_nib_n = 0;

static int q35_q2k_nib_load(const char* path, uint64_t n_tensors) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) { perror("q2knib open"); return -1; }
    uint8_t magic[8];
    if (read(fd, magic, 8) != 8 || memcmp(magic, "Q2KNIB01", 8) != 0) { close(fd); return -1; }
    uint32_t n;
    if (read(fd, &n, 4) != 4) { close(fd); return -1; }
    off_t fsz = lseek(fd, 0, SEEK_END);
    if (fsz <= 0) { close(fd); return -1; }
    const uint8_t* base = mmap(NULL, (size_t)fsz, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);
    if (base == MAP_FAILED) { perror("q2knib mmap"); return -1; }
    const uint64_t* idx = (const uint64_t*)(base + 12);
    /* 建立 GGUF tensor → sidecar 偏移映射（第 n 个 Q2K tensor → idx[n]） */
    q35_g_q2k_nib_off = malloc(sizeof(int64_t) * (n_tensors ? n_tensors : 1));
    if (!q35_g_q2k_nib_off) { munmap((void*)base, (size_t)fsz); return -1; }
    for (uint64_t i = 0; i < n_tensors; i++) q35_g_q2k_nib_off[i] = -1;
    uint32_t k = 0;
    for (uint64_t i = 0; i < n_tensors && k < n; i++)
        if ((GgmlType)q35_g_gguf.tensors[i].type == GGML_TYPE_Q2_K)
            q35_g_q2k_nib_off[i] = (int64_t)idx[k++];
    q35_g_q2k_nib_base = base;
    q35_g_q2k_nib_n = n;
    fprintf(stderr, "  V55 Q2K-nibble: sidecar %s (%u tensors, %.1f GB)\n",
            path, n, (double)fsz / 1e9);
    return 0;
}

/* V55.2: GGUF 内嵌 Q2K_NIB (type 42) 识别 —— 单一文件, 无 sidecar */
static int q35_q2k_nib_detect_embedded(uint64_t n_tensors) {
    int found = 0;
    if (!q35_g_q2k_nib_off)
        q35_g_q2k_nib_off = malloc(sizeof(int64_t) * (n_tensors ? n_tensors : 1));
    if (!q35_g_q2k_nib_off) return -1;
    for (uint64_t i = 0; i < n_tensors; i++) q35_g_q2k_nib_off[i] = -1;
    for (uint64_t i = 0; i < n_tensors; i++) {
        const GgufTensor* t = &q35_g_gguf.tensors[i];
        if ((int)t->type == 42) {
            q35_g_q2k_nib_off[i] = (int64_t)t->offset;
            found++;
        }
    }
    if (found) {
        q35_g_q2k_nib_base = (const uint8_t*)g_st.mmap_base;
        q35_g_q2k_nib_n = (uint32_t)found;
        fprintf(stderr, "  V55 Q2K-nibble: embedded GGUF (%d Q2K_NIB tensors)\n", found);
    }
    return found;
}

/* 第 r 行的 nibble 数据（148B/block）。返回 NULL 若该 tensor 无 sidecar。 */
static inline const uint8_t* q35_q2k_nib_row_ptr(const GgufTensor* t, int K, int r) {
    if (!q35_g_q2k_nib_base) return NULL;
    size_t ti = (size_t)(t - q35_g_gguf.tensors);
    int64_t off = q35_g_q2k_nib_off ? q35_g_q2k_nib_off[ti] : -1;
    if (off < 0) return NULL;
    int blocks_per_row = K / 256;
    return q35_g_q2k_nib_base + (size_t)off + (size_t)r * blocks_per_row * 148;
}

/* V55: Q2K 的 x 访问模式是交错的（原 kernel: 权重 i=4b+g 配 x[b+32g]，每 128 段）。
 * nibble kernel 顺序解包，所以进入前把 x 重排为序号顺序（数学等价，bit-exact）:
 *   x_perm[4b+g] = x[b + 32g]   (每 128 段独立) */
#define q35_Q2K_PERM_BUF ((size_t)16 * 8192)
static float* q35_g_q2k_perm = NULL;
static size_t q35_g_q2k_perm_k = 0;
static inline const float* q35_q2k_perm_x_slot(const float* x, int K, int slot) {
    if (!q35_g_q2k_perm) q35_g_q2k_perm = malloc(q35_Q2K_PERM_BUF * sizeof(float));
    if (!q35_g_q2k_perm) return x;
    if ((size_t)slot * 8192 + (size_t)K > q35_Q2K_PERM_BUF) return x;
    float* dst = q35_g_q2k_perm + (size_t)slot * 8192;
    for (int s = 0; s < K; s += 128)
        for (int b = 0; b < 32; b++)
            for (int g = 0; g < 4; g++)
                dst[s + 4 * b + g] = x[s + b + 32 * g];
    return dst;
}
static inline const block_q3_K* q35_q3k_row_ptr(const GgufTensor* t, int K, int r) {
    int blocks_per_row = K / 256;
    return (const block_q3_K*)q35_tensor_data(t)
         + (size_t)r * blocks_per_row;
}
static inline const block_q8_0* q35_q8_0_row_ptr(const GgufTensor* t, int K, int r) {
    int blocks_per_row = K / 32;
    return (const block_q8_0*)q35_tensor_data(t)
         + (size_t)r * blocks_per_row;
}


