static void q35_ipss_seed_tree(const int* ids, int n_at, int CONV_DIM, int KERNEL,
                               int NV, int HK, int HV) {
    if (n_at <= 1) return;
    int order[q35_B_MAX];
    for (int i = 0; i < n_at; i++) order[i] = ids[i];
    for (int i = 1; i < n_at; i++) {
        int v = order[i], j = i - 1;
        int pv = q35_g_tree_parent[v];
        while (j >= 0 && q35_g_tree_parent[order[j]] > pv) {
            order[j + 1] = order[j];
            j--;
        }
        order[j + 1] = v;
    }
    int i = 0;
    while (i < n_at) {
        int s0 = order[i];
        int par = q35_g_tree_parent[s0];
        int j = i + 1;
        while (j < n_at && q35_g_tree_parent[order[j]] == par) j++;
        int gsz = j - i;
        float* my0 = q35_g_ssm_tree_conv_slot[s0];
        uint16_t* rec0 = q35_g_ssm_tree_rec_slot[s0];
        const float* pc = (par < 0) ? q35_g_ssm_tree_conv_base : q35_g_ssm_tree_conv_slot[par];
        const uint16_t* pr = (par < 0) ? q35_g_ssm_tree_rec_base : q35_g_ssm_tree_rec_slot[par];
        size_t conv_bytes = (size_t)CONV_DIM * (size_t)KERNEL * sizeof(float);
        size_t rec_bytes = (size_t)NV * (size_t)HK * (size_t)HV * sizeof(uint16_t);
        if (my0 != pc) q35_pbsc_copy(my0, pc, conv_bytes);
        if (rec0 != pr) q35_pbsc_copy(rec0, pr, rec_bytes);
        if (gsz > 1) {
            q35_g_ipss_n += (gsz - 1);
            for (int k = i + 1; k < j; k++) {
                int s = order[k];
                q35_pbsc_copy(q35_g_ssm_tree_conv_slot[s], my0, conv_bytes);
                q35_pbsc_copy(q35_g_ssm_tree_rec_slot[s], rec0, rec_bytes);
            }
        }
        i = j;
    }
}

