static void q35_tree_build_ancestors(int B) {
    for (int s = 0; s < B; s++) {

        int chain[q35_B_MAX]; int n = 0;
        int cur = s;
        while (cur >= 0 && n < q35_B_MAX) { chain[n++] = cur; cur = q35_g_tree_parent[cur]; }

        for (int i = 0; i < n; i++) q35_g_tree_anc[s][i] = chain[n - 1 - i];
        q35_g_tree_anc_n[s] = n;
    }
}

