static void q35_soft_io_sync(void) {
    q35_g_soft.mmap_base = g_st.mmap_base;
    q35_g_soft.mmap_size = g_st.mmap_size;
    q35_g_soft.fd = q35_g_gguf.fd;
    q35_g_soft.keep_resident = g_st.keep_resident;
}

static size_t q35_model_resident_bytes(void) {
    if (q35_g_stream_det) return 0;   /* V56.1: 确定性流式——跳过驻留率统计 */
    q35_soft_io_sync();
    return stratum_soft_model_resident_bytes(&q35_g_soft);
}

static size_t q35_free_reclaim_bytes(void) {
    return stratum_soft_free_reclaim_bytes();
}

static int q35_detect_scene(void) {
    size_t model_sz = g_st.mmap_size ? g_st.mmap_size : g_eng.model_size;
    if (model_sz == 0) model_sz = (size_t)(11ULL << 30);
    if (g_st.keep_resident) return Q35_SCENE_HOT;
    size_t free_reclaim = q35_free_reclaim_bytes();
    size_t model_res = q35_model_resident_bytes();
    if (model_res > model_sz) model_res = model_sz;
    size_t cold = (model_sz > model_res) ? (model_sz - model_res) : 0;
    double rf = (double)model_res / (double)model_sz;
    if (q35_g_last_main_s > 2.80 && rf < 0.78)
        return Q35_SCENE_THRASH;
    if (q35_g_last_main_s > 3.10)
        return Q35_SCENE_THRASH;
    if (cold < (size_t)(384ULL << 20)
        || (rf >= 0.88 && free_reclaim >= (size_t)(512ULL << 20)))
        return Q35_SCENE_HOT;
    if (rf >= 0.82 && q35_g_last_main_s > 0.0 && q35_g_last_main_s < 2.20)
        return Q35_SCENE_HOT;
    if (rf >= 0.55 && cold <= free_reclaim
        && (q35_g_last_main_s <= 0.0 || q35_g_last_main_s < 2.70))
        return Q35_SCENE_WARM;
    if (rf >= 0.50 && free_reclaim >= cold
        && free_reclaim >= (size_t)((model_sz * 40) / 100)
        && (q35_g_last_main_s <= 0.0 || q35_g_last_main_s < 2.60))
        return Q35_SCENE_WARM;
    if (free_reclaim >= (size_t)((model_sz * 75) / 100)
        && rf >= 0.40
        && (q35_g_last_main_s <= 0.0 || q35_g_last_main_s < 2.50))
        return Q35_SCENE_WARM;
    return Q35_SCENE_THRASH;
}

static float q35_logits_entropy_topk(const float* logits, int V, int kscan, float* out_pmax) {
    if (out_pmax) *out_pmax = 0.f;
    if (!logits || V <= 0) return 0.f;
    if (kscan < 4) kscan = 4;
    if (kscan > 64) kscan = 64;
    if (kscan > V) kscan = V;
    float topv[64];
    int topn = 0;
    for (int v = 0; v < V; v++) {
        float lv = logits[v];
        if (topn < kscan) {
            int ins = topn;
            while (ins > 0 && lv > topv[ins - 1]) ins--;
            for (int k = topn; k > ins; k--) topv[k] = topv[k - 1];
            topv[ins] = lv;
            topn++;
        } else if (lv > topv[kscan - 1]) {
            int ins = kscan - 1;
            while (ins > 0 && lv > topv[ins - 1]) ins--;
            for (int k = kscan - 1; k > ins; k--) topv[k] = topv[k - 1];
            topv[ins] = lv;
        }
    }
    if (topn <= 0) return 0.f;
    float mx = topv[0];
    double sum = 0.0;
    double pbuf[64];
    for (int i = 0; i < topn; i++) {
        double e = exp((double)(topv[i] - mx));
        pbuf[i] = e;
        sum += e;
    }
    if (sum <= 0.0) return 0.f;
    double inv = 1.0 / sum;
    double H = 0.0;
    double pmax = 0.0;
    for (int i = 0; i < topn; i++) {
        double p = pbuf[i] * inv;
        if (p > pmax) pmax = p;
        if (p > 1e-12) H -= p * log(p);
    }
    if (out_pmax) *out_pmax = (float)pmax;
    return (float)H;
}

static void q35_policy_seed_env_ex(int scene, size_t free_reclaim, size_t model_sz, int force) {
    int ovr = force ? 1 : 0;
    if (scene == Q35_SCENE_THRASH) {
        int mild = (model_sz > 0 && free_reclaim >= (size_t)((model_sz * 62) / 100));
        int deep = (model_sz > 0 && free_reclaim < (size_t)((model_sz * 45) / 100));
        const char* tb = mild ? "7" : (deep ? "6" : "7");
        if (force || !getenv("STRATUM_TREE_B")) setenv("STRATUM_TREE_B", tb, ovr || !getenv("STRATUM_TREE_B"));
        if (force || !getenv("STRATUM_TREE_BRANCH"))
            setenv("STRATUM_TREE_BRANCH", "2", ovr || !getenv("STRATUM_TREE_BRANCH"));
        if (force || !getenv("STRATUM_TREE_MAXW")) {
            setenv("STRATUM_TREE_MAXW", mild ? "2" : "2", ovr || !getenv("STRATUM_TREE_MAXW"));
        }
        if (force || !getenv("STRATUM_TREE_CHAIN_D2")) setenv("STRATUM_TREE_CHAIN_D2", "1", ovr || !getenv("STRATUM_TREE_CHAIN_D2"));
        if (force || !getenv("STRATUM_TREE_EXTEND"))
            setenv("STRATUM_TREE_EXTEND", "1", 1);
        if (force || !getenv("STRATUM_TREE_EXTEND_K"))
            setenv("STRATUM_TREE_EXTEND_K", mild ? "6" : "5", ovr || !getenv("STRATUM_TREE_EXTEND_K"));
        if (force || !getenv("STRATUM_WT_STAGE_MB"))
            setenv("STRATUM_WT_STAGE_MB",
                   (free_reclaim >= (size_t)((model_sz * 50) / 100)) ? "128" : "96",
                   ovr || !getenv("STRATUM_WT_STAGE_MB"));
        if (force || !getenv("STRATUM_LM_STAGE_MB"))
            setenv("STRATUM_LM_STAGE_MB",
                   (free_reclaim >= (size_t)((model_sz * 50) / 100)) ? "128" : "96",
                   ovr || !getenv("STRATUM_LM_STAGE_MB"));
        if (force || !getenv("STRATUM_DRAFT_VOCAB")) setenv("STRATUM_DRAFT_VOCAB", "98304", ovr || !getenv("STRATUM_DRAFT_VOCAB"));
        if (force || !getenv("STRATUM_TREE_MTP_D2")) setenv("STRATUM_TREE_MTP_D2", "1", 1);
        if (force || !getenv("STRATUM_PARPREF_THREADS"))
            setenv("STRATUM_PARPREF_THREADS", mild ? "4" : "3", ovr || !getenv("STRATUM_PARPREF_THREADS"));
        if (force || !getenv("STRATUM_PARPREF_AHEAD"))
            setenv("STRATUM_PARPREF_AHEAD", mild ? "5" : "4", ovr || !getenv("STRATUM_PARPREF_AHEAD"));
        if (force || !getenv("STRATUM_HARD_TOUCH"))
            setenv("STRATUM_HARD_TOUCH", mild ? "1" : "0", ovr || !getenv("STRATUM_HARD_TOUCH"));
    } else if (scene == Q35_SCENE_WARM) {
        if (force || !getenv("STRATUM_TREE_B")) setenv("STRATUM_TREE_B", "7", 1);
        if (force || !getenv("STRATUM_TREE_BRANCH")) setenv("STRATUM_TREE_BRANCH", "2", 1);
        if (force || !getenv("STRATUM_TREE_MAXW")) setenv("STRATUM_TREE_MAXW", "2", 1);
        if (force || !getenv("STRATUM_TREE_EXTEND")) setenv("STRATUM_TREE_EXTEND", "1", 1);
        if (force || !getenv("STRATUM_TREE_EXTEND_K")) setenv("STRATUM_TREE_EXTEND_K", "5", 1);
        if (force || !getenv("STRATUM_DRAFT_VOCAB")) setenv("STRATUM_DRAFT_VOCAB", "131072", 1);
        if (force || !getenv("STRATUM_TREE_MTP_D2")) setenv("STRATUM_TREE_MTP_D2", "1", 1);
        if (force || !getenv("STRATUM_PARPREF_THREADS")) setenv("STRATUM_PARPREF_THREADS", "4", 1);
        if (force || !getenv("STRATUM_PARPREF_AHEAD")) setenv("STRATUM_PARPREF_AHEAD", "6", 1);
        if (force || !getenv("STRATUM_HARD_TOUCH")) setenv("STRATUM_HARD_TOUCH", "1", 1);
    } else {
        if (force || !getenv("STRATUM_TREE_B")) {
            const char* tbhot = "7";
            if (free_reclaim < (size_t)(6ULL << 30)) tbhot = "6";
            if (free_reclaim < (size_t)(3ULL << 30)) tbhot = "5";
            setenv("STRATUM_TREE_B", tbhot, 1);
        }
        if (force || !getenv("STRATUM_TREE_BRANCH")) setenv("STRATUM_TREE_BRANCH", "2", 1);
        if (force || !getenv("STRATUM_TREE_MAXW")) setenv("STRATUM_TREE_MAXW", "3", 1);
        if (force || !getenv("STRATUM_TREE_EXTEND")) setenv("STRATUM_TREE_EXTEND", "1", 1);
        if (force || !getenv("STRATUM_TREE_EXTEND_K")) setenv("STRATUM_TREE_EXTEND_K", "4", 1);
        if (force || !getenv("STRATUM_PARPREF_THREADS")) setenv("STRATUM_PARPREF_THREADS", "4", 1);
        if (force || !getenv("STRATUM_PARPREF_AHEAD")) setenv("STRATUM_PARPREF_AHEAD", "6", 1);
    }
    if (force || !getenv("STRATUM_TREE_COVER")) setenv("STRATUM_TREE_COVER", "0.90", ovr || !getenv("STRATUM_TREE_COVER"));
    if (force || !getenv("STRATUM_PREFETCH_AHEAD")) setenv("STRATUM_PREFETCH_AHEAD", "4", ovr || !getenv("STRATUM_PREFETCH_AHEAD"));
    if (force || !getenv("STRATUM_ASYNC_PREFETCH")) setenv("STRATUM_ASYNC_PREFETCH", "1", ovr || !getenv("STRATUM_ASYNC_PREFETCH"));
    if (force || !getenv("STRATUM_PARPREF")) setenv("STRATUM_PARPREF", "1", ovr || !getenv("STRATUM_PARPREF"));
    if (force || !getenv("STRATUM_POLICY")) setenv("STRATUM_POLICY", "1", ovr || !getenv("STRATUM_POLICY"));
}

static void q35_policy_seed_env(int scene, size_t free_reclaim, size_t model_sz) {
    q35_policy_seed_env_ex(scene, free_reclaim, model_sz, 0);
}

static void q35_policy_reseed_runtime(void) {
    size_t free_reclaim = q35_free_reclaim_bytes();
    size_t model_sz = g_st.mmap_size ? g_st.mmap_size : 0;
    if (model_sz == 0) return;
    int scene = q35_detect_scene();
    /* After max-fill, free stats drop (pages move active) but soft_warm
     * means leading weights are hot — prefer warm/extend policy. */
    size_t model_res = q35_model_resident_bytes();
    if (model_res > model_sz) model_res = model_sz;
    int mostly_hot = (model_sz > 0 && model_res >= (size_t)((model_sz * 55) / 100));
    if (q35_g_soft_warm && scene == Q35_SCENE_THRASH && mostly_hot)
        scene = Q35_SCENE_WARM;
    q35_policy_seed_env_ex(scene, free_reclaim, model_sz, 1);
    if (q35_g_soft_warm) {
        setenv("STRATUM_TREE_EXTEND", "1", 1);
        setenv("STRATUM_TREE_EXTEND_K", "4", 1);
        setenv("STRATUM_TREE_BRANCH", "2", 1);
        setenv("STRATUM_TREE_CHAIN_D2", "1", 1);
        if (!getenv("STRATUM_USER_TREE_MAXW"))
            setenv("STRATUM_TREE_MAXW", "2", 1);
        if (!getenv("STRATUM_USER_STAGE_MB")) {
            setenv("STRATUM_WT_STAGE_MB", "128", 1);
            setenv("STRATUM_LM_STAGE_MB", "128", 1);
        }
        if (!getenv("STRATUM_IO_FDS")) setenv("STRATUM_IO_FDS", "4", 1);
        if (!getenv("STRATUM_PARPREF_THREADS")) setenv("STRATUM_PARPREF_THREADS", "3", 1);
        if (!getenv("STRATUM_PARPREF_AHEAD")) setenv("STRATUM_PARPREF_AHEAD", "3", 1);
        if (!getenv("STRATUM_USER_TREE_B")) {
            setenv("STRATUM_TREE_B", "7", 1);
        }
        size_t msz = g_st.mmap_size ? g_st.mmap_size : 0;
        if (q35_g_soft_prefix_end > 0 && msz > q35_g_soft_prefix_end + (size_t)(256ULL << 20))
            setenv("STRATUM_WSTAGE", "1", 0);
    }
    q35_g_wt_stage_enable = -1;
    q35_g_hard_touch = -1;
    if (!getenv("STRATUM_USER_TREE_B")) {
        int tb_now = 0;
        const char* e_tb = getenv("STRATUM_TREE_B");
        if (e_tb) tb_now = atoi(e_tb);
        int want_tb = 7;
        if (free_reclaim < (size_t)(3ULL << 30)) want_tb = 5;
        else if (free_reclaim < (size_t)(6ULL << 30) && !mostly_hot) want_tb = 6;
        if (tb_now < want_tb) {
            char tbb[8];
            snprintf(tbb, sizeof(tbb), "%d", want_tb);
            setenv("STRATUM_TREE_B", tbb, 1);
        }
    }
    const char* sname = (scene == Q35_SCENE_HOT) ? "hot"
                      : (scene == Q35_SCENE_WARM) ? "warm" : "thrash";
    fprintf(stderr,
            "  V52 reseed: scene=%s soft=%d free=%.1fGB TREE B=%s maxw=%s extend=%s k=%s\n",
            sname, q35_g_soft_warm,
            free_reclaim / (1024.0*1024.0*1024.0),
            getenv("STRATUM_TREE_B") ? getenv("STRATUM_TREE_B") : "?",
            getenv("STRATUM_TREE_MAXW") ? getenv("STRATUM_TREE_MAXW") : "?",
            getenv("STRATUM_TREE_EXTEND") ? getenv("STRATUM_TREE_EXTEND") : "?",
            getenv("STRATUM_TREE_EXTEND_K") ? getenv("STRATUM_TREE_EXTEND_K") : "?");
}

static void q35_policy_init(Q35ScenePolicy* p, int tree_B, int branch_depth) {
    memset(p, 0, sizeof(*p));
    p->scene = q35_detect_scene();
    p->tree_B = tree_B;
    p->branch_depth = branch_depth;
    p->maxw = 4;
    {
        const char* e = getenv("STRATUM_TREE_MAXW");
        if (e) p->maxw = atoi(e);
        if (p->maxw < 1) p->maxw = 1;
        if (p->maxw > 8) p->maxw = 8;
    }
    p->chain_d2 = 1;
    {
        const char* e = getenv("STRATUM_TREE_CHAIN_D2");
        if (e) p->chain_d2 = atoi(e) ? 1 : 0;
    }
    p->extend = 0;
    {
        const char* e = getenv("STRATUM_TREE_EXTEND");
        if (e) p->extend = atoi(e) != 0;
        else p->extend = 1;
    }
    p->extend_k = 2;
    {
        const char* e = getenv("STRATUM_TREE_EXTEND_K");
        if (e) p->extend_k = atoi(e);
        p->extend_k = 4;   /* V57: safe default (was capped at 4 in the old block) */
        {
            const char* ee = getenv("STRATUM_TREE_EXTEND_K");
            if (ee) p->extend_k = atoi(ee);
        }
        if (q35_g_soft_warm && p->extend_k < 3) p->extend_k = 3;
        if (p->extend_k < 1) p->extend_k = 1;
        if (p->extend_k > 12) p->extend_k = 12;   /* V57: deep chain extension (was 4) */
    }
    p->cover = 0.90f;
    {
        const char* e = getenv("STRATUM_TREE_COVER");
        if (e) {
            float c = (float)atof(e);
            if (c > 0.5f && c < 0.999f) p->cover = c;
        }
    }
    p->accept_ema = 2.0f;
    p->entropy_ema = 1.0f;
    p->topo = Q35_TOPO_WIDE;
    p->policy_on = 1;
    {
        const char* e = getenv("STRATUM_POLICY");
        if (e) p->policy_on = atoi(e) != 0;
        if (getenv("STRATUM_NO_POLICY")) p->policy_on = 0;
    }
}

static int q35_policy_cover_width(const float* clog, int wfound, float cover, int want_cap) {
    if (wfound <= 1 || want_cap <= 1) return 1;
    float mx = clog[0];
    double sum = 0.0;
    double p[8];
    int n = wfound;
    if (n > 8) n = 8;
    for (int i = 0; i < n; i++) {
        p[i] = exp((double)(clog[i] - mx));
        sum += p[i];
    }
    if (sum <= 0.0) return 1;
    double acc = 0.0;
    int w = 1;
    for (int i = 0; i < n; i++) {
        acc += p[i] / sum;
        w = i + 1;
        if (acc >= (double)cover) break;
    }
    if (w > want_cap) w = want_cap;
    if (w < 1) w = 1;
    return w;
}


static int q35_topk_from_logits(const float* logits, int V, int k, int* out_idx, float* out_log) {
    if (!logits || V <= 0 || k <= 0 || !out_idx || !out_log) return 0;
    if (k > 512) k = 512;
    int n = 0;
    for (int v = 0; v < V; v++) {
        float lv = logits[v];
        if (n < k) {
            int ins = n;
            while (ins > 0 && lv > out_log[ins - 1]) ins--;
            for (int j = n; j > ins; j--) {
                out_idx[j] = out_idx[j - 1];
                out_log[j] = out_log[j - 1];
            }
            out_idx[ins] = v;
            out_log[ins] = lv;
            n++;
        } else if (lv > out_log[k - 1]) {
            int ins = k - 1;
            while (ins > 0 && lv > out_log[ins - 1]) ins--;
            for (int j = k - 1; j > ins; j--) {
                out_idx[j] = out_idx[j - 1];
                out_log[j] = out_log[j - 1];
            }
            out_idx[ins] = v;
            out_log[ins] = lv;
        }
    }
    return n;
}


