static void q35_bg_init(void) {
    if (q35_g_bg_inited) return;
    for (int i = 0; i < Q35_BG_CAP; i++) {
        q35_g_bg_prev[i] = -1;
        q35_g_bg_next[i] = -1;
        q35_g_bg_cnt[i] = 0;
    }
    q35_g_bg_inited = 1;
}

static unsigned q35_bg_hash(int prev, int next) {
    unsigned x = (unsigned)prev * 2654435761u ^ (unsigned)next * 1597334677u;
    return x % (unsigned)Q35_BG_CAP;
}

static void q35_bg_observe(int prev, int next) {
    if (prev < 0 || next < 0) return;
    q35_bg_init();
    unsigned h0 = q35_bg_hash(prev, next);
    for (int t = 0; t < 16; t++) {
        int i = (int)((h0 + (unsigned)t) % (unsigned)Q35_BG_CAP);
        if (q35_g_bg_cnt[i] == 0) {
            q35_g_bg_prev[i] = prev;
            q35_g_bg_next[i] = next;
            q35_g_bg_cnt[i] = 1;
            return;
        }
        if (q35_g_bg_prev[i] == prev && q35_g_bg_next[i] == next) {
            if (q35_g_bg_cnt[i] < 1000000) q35_g_bg_cnt[i]++;
            return;
        }
    }
    int victim = (int)(h0 % (unsigned)Q35_BG_CAP);
    q35_g_bg_prev[victim] = prev;
    q35_g_bg_next[victim] = next;
    q35_g_bg_cnt[victim] = 1;
}

static void q35_bg_observe_seq(const int* seq, int len) {
    if (!seq || len < 2) return;
    for (int i = 1; i < len; i++) q35_bg_observe(seq[i - 1], seq[i]);
}

static int q35_bg_propose(int prev, int* out, int max_out) {
    if (prev < 0 || !out || max_out < 1) return 0;
    q35_bg_init();
    int best_tok[8];
    int best_cnt[8];
    int n = 0;
    for (int i = 0; i < Q35_BG_CAP; i++) {
        if (q35_g_bg_cnt[i] <= 0) continue;
        if (q35_g_bg_prev[i] != prev) continue;
        int tok = q35_g_bg_next[i];
        int cnt = q35_g_bg_cnt[i];
        int ins = n;
        if (n < max_out && n < 8) {
            while (ins > 0 && cnt > best_cnt[ins - 1]) ins--;
            for (int j = n; j > ins; j--) {
                best_tok[j] = best_tok[j - 1];
                best_cnt[j] = best_cnt[j - 1];
            }
            best_tok[ins] = tok;
            best_cnt[ins] = cnt;
            n++;
        } else if (n > 0 && cnt > best_cnt[n - 1]) {
            ins = n - 1;
            while (ins > 0 && cnt > best_cnt[ins - 1]) ins--;
            for (int j = n - 1; j > ins; j--) {
                best_tok[j] = best_tok[j - 1];
                best_cnt[j] = best_cnt[j - 1];
            }
            best_tok[ins] = tok;
            best_cnt[ins] = cnt;
        }
    }
    for (int i = 0; i < n; i++) out[i] = best_tok[i];
    if (n > 0) q35_g_bg_props++;
    return n;
}

