static int q35_sg_propose(int prev2, int* out, int max_out) {
    if (prev2 < 0 || !out || max_out < 1) return 0;
    q35_sg_init();
    int best_tok[8], best_cnt[8], n = 0;
    for (int i = 0; i < Q35_SG_CAP; i++) {
        if (q35_g_sg_cnt[i] <= 0 || q35_g_sg_prev[i] != prev2) continue;
        int tok = q35_g_sg_next[i], cnt = q35_g_sg_cnt[i], ins = n;
        if (n < max_out && n < 8) {
            while (ins > 0 && cnt > best_cnt[ins - 1]) ins--;
            for (int j = n; j > ins; j--) { best_tok[j] = best_tok[j-1]; best_cnt[j] = best_cnt[j-1]; }
            best_tok[ins] = tok; best_cnt[ins] = cnt; n++;
        } else if (n > 0 && cnt > best_cnt[n - 1]) {
            ins = n - 1;
            while (ins > 0 && cnt > best_cnt[ins - 1]) ins--;
            for (int j = n - 1; j > ins; j--) { best_tok[j] = best_tok[j-1]; best_cnt[j] = best_cnt[j-1]; }
            best_tok[ins] = tok; best_cnt[ins] = cnt;
        }
    }
    for (int i = 0; i < n; i++) out[i] = best_tok[i];
    if (n > 0) q35_g_sg_props++;
    return n;
}

