static void q35_ptm_observe(int prev, int next) {
    if (prev < 0 || next < 0) return;
    for (int i = 0; i < q35_g_ptm_n; i++) {
        if (q35_g_ptm_prev[i] == prev && q35_g_ptm_next[i] == next) {
            q35_g_ptm_str[i] += 4;
            if (q35_g_ptm_str[i] > 64) q35_g_ptm_str[i] = 64;
            return;
        }
    }
    int slot;
    if (q35_g_ptm_n < Q35_PTM_CAP) slot = q35_g_ptm_n++;
    else {
        int worst = 0;
        for (int i = 1; i < q35_g_ptm_n; i++)
            if (q35_g_ptm_str[i] < q35_g_ptm_str[worst]) worst = i;
        slot = worst;
    }
    q35_g_ptm_prev[slot] = prev;
    q35_g_ptm_next[slot] = next;
    q35_g_ptm_str[slot] = 12;
}

static int q35_ptm_propose(int prev, int* out, int maxn) {
    if (!out || maxn < 1 || prev < 0 || q35_g_ptm_n <= 0) return 0;
    int idx[8];
    int n = 0;
    for (int i = 0; i < q35_g_ptm_n; i++) {
        if (q35_g_ptm_prev[i] != prev) continue;
        if (n < maxn && n < 8) idx[n++] = i;
        else if (n > 0) {
            int worst = 0;
            for (int j = 1; j < n; j++)
                if (q35_g_ptm_str[idx[j]] < q35_g_ptm_str[idx[worst]]) worst = j;
            if (q35_g_ptm_str[i] > q35_g_ptm_str[idx[worst]]) idx[worst] = i;
        }
    }
    for (int i = 0; i < n; i++) {
        int best = i;
        for (int j = i + 1; j < n; j++)
            if (q35_g_ptm_str[idx[j]] > q35_g_ptm_str[idx[best]]) best = j;
        int tmp = idx[i]; idx[i] = idx[best]; idx[best] = tmp;
    }
    for (int i = 0; i < n; i++) {
        out[i] = q35_g_ptm_next[idx[i]];
        q35_g_ptm_hit++;
    }
    return n;
}

static void q35_ptm_path(char* buf, size_t cap) {
    if (!buf || cap < 8) return;
    buf[0] = 0;
    const char* e = getenv("STRATUM_PTM_PATH");
    if (e && e[0]) {
        snprintf(buf, cap, "%s", e);
        return;
    }
    if (q35_g_gguf_path && q35_g_gguf_path[0]) {
        snprintf(buf, cap, "%s.stratum_ptm", q35_g_gguf_path);
        return;
    }
    snprintf(buf, cap, "/tmp/stratum_ptm.bin");
}

static void q35_ptm_load(void) {
    char p[1024];
    q35_ptm_path(p, sizeof(p));
    FILE* f = fopen(p, "rb");
    if (!f) return;
    int n = 0;
    if (fread(&n, sizeof(int), 1, f) != 1 || n < 0 || n > Q35_PTM_CAP) {
        fclose(f);
        return;
    }
    for (int i = 0; i < n; i++) {
        int a = 0, b = 0, s = 0;
        if (fread(&a, sizeof(int), 1, f) != 1) break;
        if (fread(&b, sizeof(int), 1, f) != 1) break;
        if (fread(&s, sizeof(int), 1, f) != 1) break;
        q35_g_ptm_prev[i] = a;
        q35_g_ptm_next[i] = b;
        q35_g_ptm_str[i] = s > 0 ? s : 8;
        if (a >= 0 && b >= 0) {
            for (int j = 0; j < q35_g_hard_n; j++) {
                if (q35_g_hard_prev[j] == a && q35_g_hard_next[j] == b) {
                    a = -1;
                    break;
                }
            }
            if (a >= 0) {
                int slot = -1;
                if (q35_g_hard_n < Q35_HARD_CAP) slot = q35_g_hard_n++;
                else {
                    int worst = 0;
                    for (int j = 1; j < q35_g_hard_n; j++)
                        if (q35_g_hard_str[j] < q35_g_hard_str[worst]) worst = j;
                    slot = worst;
                }
                q35_g_hard_prev[slot] = q35_g_ptm_prev[i];
                q35_g_hard_next[slot] = q35_g_ptm_next[i];
                q35_g_hard_str[slot] = q35_g_ptm_str[i];
            }
            q35_bg_observe(q35_g_ptm_prev[i], q35_g_ptm_next[i]);
        }
    }
    q35_g_ptm_n = n;
    q35_g_ptm_load = n;
    fclose(f);
}

static void q35_ptm_save(void) {
    if (q35_g_ptm_n <= 0 && q35_g_hard_n <= 0) return;
    char p[1024];
    q35_ptm_path(p, sizeof(p));
    for (int i = 0; i < q35_g_hard_n; i++)
        q35_ptm_observe(q35_g_hard_prev[i], q35_g_hard_next[i]);
    FILE* f = fopen(p, "wb");
    if (!f) return;
    int n = q35_g_ptm_n;
    if (n > Q35_PTM_CAP) n = Q35_PTM_CAP;
    fwrite(&n, sizeof(int), 1, f);
    for (int i = 0; i < n; i++) {
        fwrite(&q35_g_ptm_prev[i], sizeof(int), 1, f);
        fwrite(&q35_g_ptm_next[i], sizeof(int), 1, f);
        fwrite(&q35_g_ptm_str[i], sizeof(int), 1, f);
    }
    fclose(f);
    q35_g_ptm_save++;
}


static int q35_ossg_seed_match(const char* tok, size_t tlen, const char* seed) {
    if (!tok || !seed) return 0;
    if (strcmp(tok, seed) == 0) return 1;
    unsigned char raw[256];
    int rn = 0;
    const unsigned char* p = (const unsigned char*)tok;
    const unsigned char* end = p + tlen;
    while (p < end && rn < 255) {
        unsigned cp = 0;
        if (*p < 0x80) {
            cp = *p++;
        } else if ((*p & 0xE0) == 0xC0 && p + 1 < end) {
            cp = ((unsigned)(*p & 0x1F) << 6) | (p[1] & 0x3F);
            p += 2;
        } else if ((*p & 0xF0) == 0xE0 && p + 2 < end) {
            cp = ((unsigned)(*p & 0x0F) << 12)
               | ((unsigned)(p[1] & 0x3F) << 6)
               | (p[2] & 0x3F);
            p += 3;
        } else if ((*p & 0xF8) == 0xF0 && p + 3 < end) {
            cp = ((unsigned)(*p & 0x07) << 18)
               | ((unsigned)(p[1] & 0x3F) << 12)
               | ((unsigned)(p[2] & 0x3F) << 6)
               | (p[3] & 0x3F);
            p += 4;
        } else {
            return 0;
        }
        if (cp < 256) {
            raw[rn++] = (unsigned char)cp;
        } else if (cp >= 0x100 && cp <= 0x1ff) {
            int b = (int)cp - 0xA2;
            if (b < 0 || b > 255) return 0;
            raw[rn++] = (unsigned char)b;
        } else {
            return 0;
        }
    }
    raw[rn] = 0;
    return strcmp((const char*)raw, seed) == 0;
}

static void q35_ossg_ensure(void) {
    if (q35_g_ossg_ready) return;
    q35_g_ossg_ready = 1;
    q35_g_ossg_nid = 0;
    if (!q35_g_gguf_path) return;
    FILE* f = fopen(q35_g_gguf_path, "rb");
    if (!f) return;
    char magic[4];
    if (fread(magic, 1, 4, f) != 4 || memcmp(magic, "GGUF", 4) != 0) {
        fclose(f);
        return;
    }
    uint32_t ver = 0;
    uint64_t n_tensors = 0, n_kv = 0;
    if (fread(&ver, 4, 1, f) != 1) { fclose(f); return; }
    if (fread(&n_tensors, 8, 1, f) != 1) { fclose(f); return; }
    if (fread(&n_kv, 8, 1, f) != 1) { fclose(f); return; }
    (void)ver; (void)n_tensors;
    for (uint64_t ki = 0; ki < n_kv; ki++) {
        uint64_t klen = 0;
        if (fread(&klen, 8, 1, f) != 1) break;
        if (klen > (1u << 20)) break;
        char* key = (char*)malloc((size_t)klen + 1);
        if (!key) break;
        if (fread(key, 1, (size_t)klen, f) != (size_t)klen) { free(key); break; }
        key[klen] = 0;
        uint32_t t = 0;
        if (fread(&t, 4, 1, f) != 1) { free(key); break; }
        if (t == 9) {
            uint32_t at = 0;
            uint64_t n = 0;
            if (fread(&at, 4, 1, f) != 1) { free(key); break; }
            if (fread(&n, 8, 1, f) != 1) { free(key); break; }
            if (strcmp(key, "tokenizer.ggml.tokens") == 0 && at == 8) {
                int nseeds = 0;
                while (q35_ossg_seed_phrases[nseeds]) nseeds++;
                int* found = (int*)calloc((size_t)nseeds, sizeof(int));
                if (!found) { free(key); break; }
                for (uint64_t ti = 0; ti < n; ti++) {
                    uint64_t sl = 0;
                    if (fread(&sl, 8, 1, f) != 1) break;
                    if (sl > (1u << 20)) break;
                    char* s = (char*)malloc((size_t)sl + 1);
                    if (!s) break;
                    if (fread(s, 1, (size_t)sl, f) != (size_t)sl) { free(s); break; }
                    s[sl] = 0;
                    for (int si = 0; si < nseeds; si++) {
                        if (found[si]) continue;
                        if (q35_ossg_seed_match(s, (size_t)sl, q35_ossg_seed_phrases[si])) {
                            found[si] = 1;
                            if (q35_g_ossg_nid < 48)
                                q35_g_ossg_ids[q35_g_ossg_nid++] = (int)ti;
                        }
                    }
                    free(s);
                    int all = 1;
                    for (int si = 0; si < nseeds; si++) if (!found[si]) { all = 0; break; }
                    if (all) {
                        for (uint64_t tj = ti + 1; tj < n; tj++) {
                            uint64_t sl2 = 0;
                            if (fread(&sl2, 8, 1, f) != 1) { tj = n; break; }
                            if (fseeko(f, (off_t)sl2, SEEK_CUR) != 0) { tj = n; break; }
                        }
                        break;
                    }
                }
                free(found);
                free(key);
                break;
            } else if (at == 8) {
                for (uint64_t i = 0; i < n; i++) {
                    uint64_t sl = 0;
                    if (fread(&sl, 8, 1, f) != 1) { free(key); key = NULL; break; }
                    if (fseeko(f, (off_t)sl, SEEK_CUR) != 0) { free(key); key = NULL; break; }
                }
                if (!key) break;
            } else {
                static const int sizes[14] = {1,1,2,2,4,4,4,8,0,0,1,1,8,4};
                int es = (at < 14) ? sizes[at] : 0;
                if (es > 0) {
                    if (fseeko(f, (off_t)es * (off_t)n, SEEK_CUR) != 0) { free(key); break; }
                }
            }
        } else if (t == 8) {
            uint64_t sl = 0;
            if (fread(&sl, 8, 1, f) != 1) { free(key); break; }
            if (fseeko(f, (off_t)sl, SEEK_CUR) != 0) { free(key); break; }
        } else {
            static const int sizes[14] = {1,1,2,2,4,4,4,8,0,0,1,1,8,4};
            int es = (t < 14) ? sizes[t] : 0;
            if (es > 0) {
                if (fseeko(f, es, SEEK_CUR) != 0) { free(key); break; }
            }
        }
        free(key);
    }
    fclose(f);
    if (q35_g_ossg_nid > 1) {
        for (int i = 0; i < q35_g_ossg_nid; i++) {
            int best = i;
            for (int j = i + 1; j < q35_g_ossg_nid; j++)
                if (q35_g_ossg_ids[j] > q35_g_ossg_ids[best]) best = j;
            int tmp = q35_g_ossg_ids[i];
            q35_g_ossg_ids[i] = q35_g_ossg_ids[best];
            q35_g_ossg_ids[best] = tmp;
        }
    }
    if (q35_g_ossg_nid > 0) q35_g_ossg_n = 1;
}

static void q35_ctxh_observe(int p2, int p1, int nx) {
    if (p1 < 0 || nx < 0) return;
    if (p2 < 0) p2 = -1;
    for (int i = 0; i < q35_g_ctxh_n; i++) {
        if (q35_g_ctxh_p2[i] == p2 && q35_g_ctxh_p1[i] == p1
            && q35_g_ctxh_nx[i] == nx) {
            q35_g_ctxh_str[i] += 10;
            if (q35_g_ctxh_str[i] > 80) q35_g_ctxh_str[i] = 80;
            q35_g_ctxhard_obs++;
            return;
        }
    }
    int slot = -1;
    if (q35_g_ctxh_n < Q35_CTXH_CAP) slot = q35_g_ctxh_n++;
    else {
        int worst = 0;
        for (int i = 1; i < q35_g_ctxh_n; i++)
            if (q35_g_ctxh_str[i] < q35_g_ctxh_str[worst]) worst = i;
        slot = worst;
    }
    q35_g_ctxh_p2[slot] = p2;
    q35_g_ctxh_p1[slot] = p1;
    q35_g_ctxh_nx[slot] = nx;
    q35_g_ctxh_str[slot] = 20;
    q35_g_ctxhard_obs++;
}

static int q35_ctxh_propose(int p2, int p1, int* out, int maxn) {
    if (!out || maxn < 1 || p1 < 0 || q35_g_ctxh_n <= 0) return 0;
    int idx[8];
    int n = 0;
    for (int i = 0; i < q35_g_ctxh_n; i++) {
        if (q35_g_ctxh_p1[i] != p1) continue;
        int score = q35_g_ctxh_str[i];
        if (p2 >= 0 && q35_g_ctxh_p2[i] == p2) score += 40;
        else if (q35_g_ctxh_p2[i] >= 0 && p2 >= 0 && q35_g_ctxh_p2[i] != p2)
            score -= 30;
        if (score < 8) continue;
        if (n < maxn && n < 8) idx[n++] = i;
        else if (n > 0) {
            int worst = 0;
            for (int j = 1; j < n; j++) {
                int sj = q35_g_ctxh_str[idx[j]];
                int sw = q35_g_ctxh_str[idx[worst]];
                if (p2 >= 0 && q35_g_ctxh_p2[idx[j]] == p2) sj += 40;
                if (p2 >= 0 && q35_g_ctxh_p2[idx[worst]] == p2) sw += 40;
                if (sj < sw) worst = j;
            }
            int sw = q35_g_ctxh_str[idx[worst]];
            if (p2 >= 0 && q35_g_ctxh_p2[idx[worst]] == p2) sw += 40;
            if (score > sw) idx[worst] = i;
        }
    }
    for (int i = 0; i < n; i++) {
        int best = i;
        for (int j = i + 1; j < n; j++) {
            int sb = q35_g_ctxh_str[idx[best]];
            int sj = q35_g_ctxh_str[idx[j]];
            if (p2 >= 0 && q35_g_ctxh_p2[idx[best]] == p2) sb += 40;
            if (p2 >= 0 && q35_g_ctxh_p2[idx[j]] == p2) sj += 40;
            if (sj > sb) best = j;
        }
        int tmp = idx[i]; idx[i] = idx[best]; idx[best] = tmp;
    }
    int no = 0;
    for (int i = 0; i < n && no < maxn; i++) {
        int t = q35_g_ctxh_nx[idx[i]];
        int d = 0;
        for (int j = 0; j < no; j++) if (out[j] == t) { d = 1; break; }
        if (d) continue;
        out[no++] = t;
        q35_g_ctxhard_hit++;
        q35_g_ctxhard_prop++;
    }
    return no;
}

static int q35_logit_rank(const float* logits, int V, int truth) {
    if (!logits || V <= 0 || truth < 0 || truth >= V) return -1;
    float tv = logits[truth];
    int rank = 0;
    for (int v = 0; v < V; v++) {
        float lv = logits[v];
        if (lv > tv || (lv == tv && v < truth)) rank++;
    }
    return rank;
}

static int q35_rift_scan(const float* logits, int V, float delta, int* out, int maxn) {
    if (!logits || V <= 0 || !out || maxn < 1) return 0;
    if (delta < 0.75f) delta = 0.75f;
    int kk = maxn * 8;
    if (kk < 64) kk = 64;
    if (kk > 400) kk = 400;
    if (kk < maxn) kk = maxn;
    int tmp[400];
    float lg[400];
    int nt = q35_topk_from_logits(logits, V, kk, tmp, lg);
    if (nt < 1) return 0;
    float mx = lg[0];
    float thr = mx - delta;
    int n = 0;
    for (int i = 0; i < nt && n < maxn; i++) {
        if (lg[i] >= thr || i < 2) out[n++] = tmp[i];
    }
    if (n < maxn && n < nt) {
        for (int i = n; i < nt && n < maxn; i++) out[n++] = tmp[i];
    }
    if (n > 0) {
        q35_g_rift_n++;
        q35_g_rift_slots += n;
    }
    return n;
}

static void q35_mtp_probe_store(int parent, const float* logits) {
    if (!logits || parent < 0) return;
    int V = q35_g_cfg.vocab_size;
    if (V <= 0) return;
    int s = q35_g_probe_bank_slot % Q35_PROBE_BANK;
    float logs[Q35_PROBE_K];
    q35_g_probe_bank_prev[s] = parent;
    q35_g_probe_bank_n[s] = q35_topk_from_logits(logits, V, Q35_PROBE_K,
        q35_g_probe_bank_tok[s], logs);
    q35_g_probe_bank_slot = (s + 1) % Q35_PROBE_BANK;
}

static int q35_mtp_probe_lookup(int parent, int truth) {
    if (parent < 0 || truth < 0) return -2;
    for (int i = 0; i < Q35_PROBE_BANK; i++) {
        int s = (q35_g_probe_bank_slot - 1 - i + Q35_PROBE_BANK * 4) % Q35_PROBE_BANK;
        if (q35_g_probe_bank_n[s] <= 0) continue;
        if (q35_g_probe_bank_prev[s] != parent) continue;
        for (int r = 0; r < q35_g_probe_bank_n[s]; r++)
            if (q35_g_probe_bank_tok[s][r] == truth) return r;
        return -1;
    }
    return -2;
}

static void q35_mtp_probe_observe(int parent, int truth) {
    if (truth < 0) return;
    int rank = q35_mtp_probe_lookup(parent, truth);
    q35_g_probe_obs++;
    if (rank >= 0 && rank < 8) q35_g_probe_top8++;
    if (rank >= 0 && rank < 16) q35_g_probe_top16++;
    if (rank >= 0 && rank < 32) q35_g_probe_top32++;
    if (rank >= 0 && rank < 64) q35_g_probe_top64++;
    if (rank >= 0 && rank < 128) q35_g_probe_top128++;
    if (rank >= 0 && rank < 256) q35_g_probe_top256++;
    if (rank < 0) q35_g_probe_miss++;
    else q35_g_probe_rank_sum += rank;
    if (getenv("STRATUM_SPINE_DEBUG") || getenv("STRATUM_MTP_PROBE")) {
        fprintf(stderr, "  mtp-probe: parent=%d truth=%d rank=%d bank=%d\n",
            parent, truth, rank, Q35_PROBE_BANK);
    }
}

static void q35_mtp_probe_observe_exact(int parent, int truth, const float* logits) {
    if (truth < 0) return;
    int rank = -1;
    if (logits) {
        int V = q35_g_cfg.vocab_size;
        rank = q35_logit_rank(logits, V, truth);
        if (truth >= 0 && truth < 1024) {
            float tv = logits[truth];
            int better = 0;
            int lim = V < 1024 ? V : 1024;
            for (int v = 0; v < lim; v++) {
                if (logits[v] > tv || (logits[v] == tv && v < truth)) better++;
                if (better >= 8) break;
            }
            if (better < 8) q35_g_lvd_hit++;
        }
    } else {
        rank = q35_mtp_probe_lookup(parent, truth);
        if (rank == -2) rank = -1;
    }
    q35_g_probe_obs++;
    if (rank >= 0 && rank < 8) q35_g_probe_top8++;
    if (rank >= 0 && rank < 16) q35_g_probe_top16++;
    if (rank >= 0 && rank < 32) q35_g_probe_top32++;
    if (rank >= 0 && rank < 64) q35_g_probe_top64++;
    if (rank >= 0 && rank < 128) q35_g_probe_top128++;
    if (rank >= 0 && rank < 256) q35_g_probe_top256++;
    if (rank < 0) q35_g_probe_miss++;
    else q35_g_probe_rank_sum += rank;
    if (getenv("STRATUM_SPINE_DEBUG") || getenv("STRATUM_MTP_PROBE")) {
        fprintf(stderr, "  mtp-probe-x: parent=%d truth=%d rank=%d\n",
            parent, truth, rank);
    }
}

static int q35_lvd_range(const float* logits, int V, int lo, int hi,
                          int* out, int maxn) {
    if (!logits || V <= 0 || !out || maxn < 1) return 0;
    if (lo < 0) lo = 0;
    if (hi > V) hi = V;
    if (lo >= hi) return 0;
    int k = maxn;
    if (k > 24) k = 24;
    int idx[24];
    float lg[24];
    int n = 0;
    for (int v = lo; v < hi; v++) {
        float lv = logits[v];
        if (n < k) {
            int ins = n;
            while (ins > 0 && lv > lg[ins - 1]) ins--;
            for (int j = n; j > ins; j--) {
                idx[j] = idx[j - 1];
                lg[j] = lg[j - 1];
            }
            idx[ins] = v;
            lg[ins] = lv;
            n++;
        } else if (lv > lg[k - 1]) {
            int ins = k - 1;
            while (ins > 0 && lv > lg[ins - 1]) ins--;
            for (int j = k - 1; j > ins; j--) {
                idx[j] = idx[j - 1];
                lg[j] = lg[j - 1];
            }
            idx[ins] = v;
            lg[ins] = lv;
        }
    }
    for (int i = 0; i < n; i++) out[i] = idx[i];
    return n;
}

static int q35_lvd_propose(const float* logits, int* out, int maxn) {
    if (!logits || !out || maxn < 1) return 0;
    int V = q35_g_cfg.vocab_size;
    if (V <= 0) return 0;
    int n = 0;
    int win[12];
    int lim0 = V < 1024 ? V : 1024;
    {
        int cand[48]; float cl[48]; int nc = 0;
        for (int v = 0; v < lim0; v++) {
            float lv = logits[v];
            if (nc < 40) {
                int ins = nc;
                while (ins > 0 && lv > cl[ins - 1]) ins--;
                for (int j = nc; j > ins; j--) { cand[j]=cand[j-1]; cl[j]=cl[j-1]; }
                cand[ins]=v; cl[ins]=lv; nc++;
            } else if (lv > cl[39]) {
                int ins = 39;
                while (ins > 0 && lv > cl[ins - 1]) ins--;
                for (int j = 39; j > ins; j--) { cand[j]=cand[j-1]; cl[j]=cl[j-1]; }
                cand[ins]=v; cl[ins]=lv;
            }
        }
        for (int i = 0; i < nc && n < maxn; i++) out[n++] = cand[i];
    }
    if (V > 1024) {
        int hi = V < 4096 ? V : 4096;
        int nw = q35_lvd_range(logits, V, 1024, hi, win, 4);
        for (int i = 0; i < nw && n < maxn; i++) {
            int t = win[i];
            int d = 0;
            for (int j = 0; j < n; j++) if (out[j] == t) { d = 1; break; }
            if (!d) out[n++] = t;
        }
    }
    for (int i = 0; i < q35_g_hard_n && n < maxn; i++) {
        int h = q35_g_hard_next[i];
        if (h < 0 || h >= V) continue;
        int lo = h - 96;
        int hi = h + 97;
        if (lo < 0) lo = 0;
        if (hi > V) hi = V;
        int band[4];
        int nb = q35_lvd_range(logits, V, lo, hi, band, 2);
        for (int j = 0; j < nb && n < maxn; j++) {
            int t = band[j];
            int d = 0;
            for (int k = 0; k < n; k++) if (out[k] == t) { d = 1; break; }
            if (!d) {
                out[n++] = t;
                q35_g_band_n++;
                q35_g_band_slots++;
            }
        }
    }
    if (n > 0) {
        q35_g_lvd_n++;
        q35_g_lvd_slots += n;
    }
    return n;
}

static int q35_abyss_propose(const float* logits, int* out, int maxn, int skip_top) {
    if (!logits || !out || maxn < 1) return 0;
    int V = q35_g_cfg.vocab_size;
    if (V <= 0) return 0;
    int k = 400;
    if (k > V) k = V;
    int tmp[400];
    float lg[400];
    int nt = q35_topk_from_logits(logits, V, k, tmp, lg);
    if (nt < 1) return 0;
    int n = 0;
    int start = skip_top;
    if (start < 0) start = 0;
    if (start > nt) start = nt;
    int near = maxn / 2;
    if (near < 2) near = 2;
    for (int i = start; i < nt && n < near && n < maxn; i++)
        out[n++] = tmp[i];
    static const int deep_idx[] = {32, 48, 64, 96, 128, 160, 200, 245, 280, 320, 360, 390};
    for (int di = 0; di < (int)(sizeof(deep_idx)/sizeof(deep_idx[0])) && n < maxn; di++) {
        int ix = deep_idx[di];
        if (ix >= nt) continue;
        if (ix < start) continue;
        int t = tmp[ix];
        int dup = 0;
        for (int j = 0; j < n; j++) if (out[j] == t) { dup = 1; break; }
        if (!dup) out[n++] = t;
    }
    for (int i = start; i < nt && n < maxn; i += 7) {
        int t = tmp[i];
        int dup = 0;
        for (int j = 0; j < n; j++) if (out[j] == t) { dup = 1; break; }
        if (!dup) out[n++] = t;
    }
    if (n > 0) {
        q35_g_abyss_n++;
        q35_g_abyss_slots += n;
    }
    return n;
}

static int q35_ora_chain(int start, int* out, int maxn,
                         const int* hist, int hlen, int ngram_order) {
    if (!out || maxn < 1 || start < 0) return 0;
    int n = 0;
    int cur = start;
    int local[64];
    int ln = 0;
    if (hist && hlen > 0) {
        int ncopy = hlen;
        if (ncopy > 48) ncopy = 48;
        memcpy(local, hist + (hlen - ncopy), sizeof(int) * ncopy);
        ln = ncopy;
    }
    if (ln < 63) local[ln++] = start;
    for (int hop = 0; hop < maxn; hop++) {
        int props[8]; int np = 0;
        int o[Q35_ORA_K];
        int no = q35_ora_propose(cur, o, Q35_ORA_K);
        for (int i = 0; i < no && np < 8; i++) props[np++] = o[i];
        {
            int v[4];
            int nv = q35_vtb_propose(cur, v, 4);
            for (int i = 0; i < nv && np < 8; i++) {
                int t = v[i];
                int d = 0;
                for (int j = 0; j < np; j++) if (props[j] == t) { d = 1; break; }
                if (!d) props[np++] = t;
            }
        }
        if (ngram_order > 0 && ln > 0) {
            int g[4];
            int ng = q35_ngram_propose_multi(local, ln, ngram_order, g, 4);
            for (int i = 0; i < ng && np < 8; i++) {
                int t = g[i];
                int d = 0;
                for (int j = 0; j < np; j++) if (props[j] == t) { d = 1; break; }
                if (!d) props[np++] = t;
            }
        }
        {
            int b[3];
            int nb = q35_bg_propose(cur, b, 3);
            for (int i = 0; i < nb && np < 8; i++) {
                int t = b[i];
                int d = 0;
                for (int j = 0; j < np; j++) if (props[j] == t) { d = 1; break; }
                if (!d) props[np++] = t;
            }
        }
        if (np < 1) break;
        int nxt = props[0];
        out[n++] = nxt;
        cur = nxt;
        if (ln < 63) local[ln++] = nxt;
        else {
            for (int i = 1; i < ln; i++) local[i - 1] = local[i];
            local[ln - 1] = nxt;
        }
    }
    return n;
}

static int q35_draft_union_scored(const float* logits, int V, int band,
                                  const int* hist, int hlen, int ngram_order,
                                  int want, int* cand, float* clog) {
    if (!logits || !cand || !clog || want < 1 || V <= 0) return 0;
    if (band <= 0 || band > V) band = V;
    if (want > 8) want = 8;
    int c0 = stratum_argmax(logits, V);
    if (c0 < 0) c0 = 0;
    float c0l = logits[c0];
    int wfound = q35_topk_from_logits(logits, band, want, cand, clog);
    if (wfound < 1) {
        cand[0] = c0;
        clog[0] = c0l;
        wfound = 1;
    } else {
        int has = -1;
        for (int j = 0; j < wfound; j++) if (cand[j] == c0) { has = j; break; }
        if (has < 0) {
            if (wfound < want) {
                for (int j = wfound; j > 0; j--) {
                    cand[j] = cand[j - 1];
                    clog[j] = clog[j - 1];
                }
                cand[0] = c0;
                clog[0] = c0l;
                wfound++;
            } else {
                int worst = wfound - 1;
                for (int j = 1; j < wfound; j++)
                    if (clog[j] < clog[worst]) worst = j;
                for (int j = worst; j > 0; j--) {
                    cand[j] = cand[j - 1];
                    clog[j] = clog[j - 1];
                }
                cand[0] = c0;
                clog[0] = c0l;
            }
        } else if (has > 0) {
            for (int j = has; j > 0; j--) {
                cand[j] = cand[j - 1];
                clog[j] = clog[j - 1];
            }
            cand[0] = c0;
            clog[0] = c0l;
        } else {
            clog[0] = c0l;
        }
    }
    int props[16];
    int np = 0;
    if (hist && hlen > 1 && ngram_order > 0) {
        int ngc[6];
        int nng = q35_ngram_propose_multi(hist, hlen, ngram_order, ngc, 6);
        for (int i = 0; i < nng && np < 16; i++) props[np++] = ngc[i];
    }
    if (hist && hlen > 0) {
        int bgc[4];
        int nbg = q35_bg_propose(hist[hlen - 1], bgc, 4);
        for (int i = 0; i < nbg && np < 16; i++) {
            int tok = bgc[i];
            int dup = 0;
            for (int j = 0; j < np; j++) if (props[j] == tok) { dup = 1; break; }
            if (!dup) props[np++] = tok;
        }
    }
    if (hist && hlen >= 2) {
        int sgc[3];
        int nsg = q35_sg_propose(hist[hlen - 2], sgc, 3);
        for (int i = 0; i < nsg && np < 16; i++) {
            int tok = sgc[i];
            int dup = 0;
            for (int j = 0; j < np; j++) if (props[j] == tok) { dup = 1; break; }
            if (!dup) props[np++] = tok;
        }
    }
    if (hist && hlen >= 2) {
        int a = hist[hlen - 2];
        int b = hist[hlen - 1];
        int dd = b - a;
        if (dd != 0 && dd > -512 && dd < 512) {
            int tok = b + dd;
            if (tok >= 0 && tok < V) {
                int dup = 0;
                for (int j = 0; j < np; j++) if (props[j] == tok) { dup = 1; break; }
                if (!dup) props[np++] = tok;
            }
        }
    }
    if (hist && hlen > 0) {
        int vtb[4];
        int nv = q35_vtb_propose(hist[hlen - 1], vtb, 4);
        for (int i = 0; i < nv && np < 16; i++) {
            int tok = vtb[i];
            if (tok < 0 || tok >= V) continue;
            int dup = 0;
            for (int j = 0; j < np; j++) if (props[j] == tok) { dup = 1; break; }
            if (!dup) {
                props[np++] = tok;
                q35_g_vtb_hit++;
            }
        }
    }
    if (q35_g_main_res_n > 0) {
        for (int i = 0; i < q35_g_main_res_n && np < 16; i++) {
            int tok = q35_g_main_res_tok[i];
            int dup = 0;
            for (int j = 0; j < np; j++) if (props[j] == tok) { dup = 1; break; }
            if (!dup) {
                props[np++] = tok;
                q35_g_res_hits++;
            }
        }
    }
    for (int i = 0; i < np; i++) {
        int tok = props[i];
        if (tok < 0 || tok >= V) continue;
        float lv = logits[tok];
        int idx = -1;
        for (int j = 0; j < wfound; j++) if (cand[j] == tok) { idx = j; break; }
        if (idx >= 0) {
            if (lv > clog[idx]) clog[idx] = lv;
            continue;
        }
        if (wfound < want) {
            int ins = wfound;
            while (ins > 0 && lv > clog[ins - 1]) ins--;
            for (int j = wfound; j > ins; j--) {
                cand[j] = cand[j - 1];
                clog[j] = clog[j - 1];
            }
            cand[ins] = tok;
            clog[ins] = lv;
            wfound++;
            q35_g_bg_hits++;
        } else if (wfound >= 2) {
            int worst = 1;
            for (int j = 2; j < wfound; j++)
                if (clog[j] < clog[worst]) worst = j;
            if (lv > clog[worst]) {
                cand[worst] = tok;
                clog[worst] = lv;
                int ins = worst;
                while (ins > 0 && clog[ins] > clog[ins - 1]) {
                    int tt = cand[ins]; float tl = clog[ins];
                    cand[ins] = cand[ins - 1]; clog[ins] = clog[ins - 1];
                    cand[ins - 1] = tt; clog[ins - 1] = tl;
                    ins--;
                }
                q35_g_bg_hits++;
            }
        }
    }
    if (wfound > 1 && cand[0] != c0) {
        int has = -1;
        for (int j = 0; j < wfound; j++) if (cand[j] == c0) { has = j; break; }
        if (has > 0) {
            for (int j = has; j > 0; j--) {
                cand[j] = cand[j - 1];
                clog[j] = clog[j - 1];
            }
            cand[0] = c0;
            clog[0] = c0l;
        }
    }
    return wfound;
}


static int q35_draft_reserve_d1(int* cand, float* clog, int wfound, int want,
                                const float* logits, int V,
                                const int* hist, int hlen, int ngram_order) {
    if (!cand || !clog || !logits || V <= 0 || want < 2 || wfound < 1) return wfound;
    if (want > 8) want = 8;
    int props[16];
    int ppri[16];
    int np = 0;
    if (hist && hlen > 1 && ngram_order > 0) {
        int ngc[6];
        int nng = q35_ngram_propose_multi(hist, hlen, ngram_order, ngc, 6);
        for (int i = 0; i < nng && np < 16; i++) {
            int tok = ngc[i];
            if (tok < 0 || tok >= V || tok == cand[0]) continue;
            int dup = 0;
            for (int j = 0; j < np; j++) if (props[j] == tok) { dup = 1; break; }
            if (!dup) { props[np] = tok; ppri[np] = 3; np++; }
        }
    }
    if (hist && hlen > 0) {
        int vtb[4];
        int nv = q35_vtb_propose(hist[hlen - 1], vtb, 4);
        for (int i = 0; i < nv && np < 16; i++) {
            int tok = vtb[i];
            if (tok < 0 || tok >= V || tok == cand[0]) continue;
            int dup = 0;
            for (int j = 0; j < np; j++) if (props[j] == tok) { dup = 1; break; }
            if (!dup) { props[np] = tok; ppri[np] = 4; np++; q35_g_vtb_hit++; }
        }
        int bgc[4];
        int nbg = q35_bg_propose(hist[hlen - 1], bgc, 4);
        for (int i = 0; i < nbg && np < 16; i++) {
            int tok = bgc[i];
            if (tok < 0 || tok >= V || tok == cand[0]) continue;
            int dup = 0;
            for (int j = 0; j < np; j++) if (props[j] == tok) { dup = 1; break; }
            if (!dup) { props[np] = tok; ppri[np] = 2; np++; }
        }
    }
    if (hist && hlen >= 2) {
        int sgc[3];
        int nsg = q35_sg_propose(hist[hlen - 2], sgc, 3);
        for (int i = 0; i < nsg && np < 16; i++) {
            int tok = sgc[i];
            if (tok < 0 || tok >= V || tok == cand[0]) continue;
            int dup = 0;
            for (int j = 0; j < np; j++) if (props[j] == tok) { dup = 1; break; }
            if (!dup) { props[np] = tok; ppri[np] = 2; np++; }
        }
        int a = hist[hlen - 2];
        int b = hist[hlen - 1];
        int dd = b - a;
        if (dd != 0 && dd > -512 && dd < 512) {
            int tok = b + dd;
            if (tok >= 0 && tok < V && tok != cand[0]) {
                int dup = 0;
                for (int j = 0; j < np; j++) if (props[j] == tok) { dup = 1; break; }
                if (!dup) { props[np] = tok; ppri[np] = 2; np++; }
            }
        }
    }
    if (q35_g_main_res_n > 0) {
        for (int i = 0; i < q35_g_main_res_n && np < 16; i++) {
            int tok = q35_g_main_res_tok[i];
            if (tok < 0 || tok >= V || tok == cand[0]) continue;
            int dup = 0;
            for (int j = 0; j < np; j++) if (props[j] == tok) { dup = 1; break; }
            if (!dup) { props[np] = tok; ppri[np] = (i < 3) ? 1 : 0; np++; }
        }
    }
    if ((q35_g_d1_miss_streak > 0 || q35_g_last_plen <= 1) && want >= 3) {
        int extra[4];
        float elg[4];
        int ne = q35_topk_from_logits(logits, V, 4, extra, elg);
        for (int i = 0; i < ne && np < 16; i++) {
            int tok = extra[i];
            if (tok < 0 || tok >= V || tok == cand[0]) continue;
            int dup = 0;
            for (int j = 0; j < np; j++) if (props[j] == tok) { dup = 1; break; }
            for (int j = 0; !dup && j < wfound; j++) if (cand[j] == tok) { dup = 1; break; }
            if (!dup) { props[np] = tok; ppri[np] = 4; np++; }
        }
    }
    if (np < 1) return wfound;
    for (int i = 0; i < np; i++) {
        int tok = props[i];
        int has = -1;
        for (int j = 0; j < wfound; j++) if (cand[j] == tok) { has = j; break; }
        if (has >= 0) continue;
        float lv = logits[tok];
        int force = (ppri[i] >= 2) || (q35_g_d1_miss_streak > 0) || (q35_g_last_plen <= 1);
        if (force) {
            float floor_lv = clog[0] - (ppri[i] >= 3 ? 1.2f : 2.0f);
            if (lv < floor_lv) lv = floor_lv;
        }
        if (wfound < want) {
            int ins = wfound;
            while (ins > 1 && lv > clog[ins - 1]) ins--;
            if (ins < 1) ins = 1;
            for (int j = wfound; j > ins; j--) {
                cand[j] = cand[j - 1];
                clog[j] = clog[j - 1];
            }
            cand[ins] = tok;
            clog[ins] = lv;
            wfound++;
            q35_g_res_reserve++;
            continue;
        }
        if (wfound < 2) continue;
        int worst = 1;
        for (int j = 2; j < wfound; j++)
            if (clog[j] < clog[worst]) worst = j;
        int take = 0;
        if (lv > clog[worst]) take = 1;
        else if (force && ppri[i] >= 2) take = 1;
        else if (force && q35_g_d1_miss_streak >= 2 && worst > 0) take = 1;
        if (!take) continue;
        cand[worst] = tok;
        clog[worst] = lv;
        int ins = worst;
        while (ins > 1 && clog[ins] > clog[ins - 1]) {
            int tt = cand[ins]; float tl = clog[ins];
            cand[ins] = cand[ins - 1]; clog[ins] = clog[ins - 1];
            cand[ins - 1] = tt; clog[ins - 1] = tl;
            ins--;
        }
        q35_g_res_reserve++;
    }
    return wfound;
}

static int q35_draft_compose_d1(const float* logits, int V, int band,
                                 const int* hist, int hlen, int ngram_order,
                                 int want, int* cand, float* clog) {
    if (!logits || !cand || !clog || want < 1 || V <= 0) return 0;
    if (want > 8) want = 8;
    if (band <= 0 || band > V) band = V;
    int mtp[8]; float mlg[8];
    int nm = q35_draft_union_scored(logits, V, band, hist, hlen, ngram_order, want, mtp, mlg);
    if (nm < 1) {
        mtp[0] = stratum_argmax(logits, V);
        if (mtp[0] < 0) mtp[0] = 0;
        mlg[0] = logits[mtp[0]];
        nm = 1;
    }
    int histp[8];
    int nh = 0;
    if (hist && hlen > 1 && ngram_order > 0) {
        int ngc[6];
        int nng = q35_ngram_propose_multi(hist, hlen, ngram_order, ngc, 6);
        for (int i = 0; i < nng && nh < 8; i++) {
            int tok = ngc[i];
            if (tok < 0 || tok >= V || tok == mtp[0]) continue;
            int dup = 0;
            for (int j = 0; j < nh; j++) if (histp[j] == tok) { dup = 1; break; }
            if (!dup) histp[nh++] = tok;
        }
    }
    if (hist && hlen > 0) {
        int bgc[4];
        int nbg = q35_bg_propose(hist[hlen - 1], bgc, 4);
        for (int i = 0; i < nbg && nh < 8; i++) {
            int tok = bgc[i];
            if (tok < 0 || tok >= V || tok == mtp[0]) continue;
            int dup = 0;
            for (int j = 0; j < nh; j++) if (histp[j] == tok) { dup = 1; break; }
            if (!dup) histp[nh++] = tok;
        }
    }
    if (hist && hlen >= 2) {
        int sgc[3];
        int nsg = q35_sg_propose(hist[hlen - 2], sgc, 3);
        for (int i = 0; i < nsg && nh < 8; i++) {
            int tok = sgc[i];
            if (tok < 0 || tok >= V || tok == mtp[0]) continue;
            int dup = 0;
            for (int j = 0; j < nh; j++) if (histp[j] == tok) { dup = 1; break; }
            if (!dup) histp[nh++] = tok;
        }
        int a = hist[hlen - 2], b = hist[hlen - 1], dd = b - a;
        if (dd != 0 && dd > -512 && dd < 512) {
            int tok = b + dd;
            if (tok >= 0 && tok < V && tok != mtp[0]) {
                int dup = 0;
                for (int j = 0; j < nh; j++) if (histp[j] == tok) { dup = 1; break; }
                if (!dup) histp[nh++] = tok;
            }
            tok = b + 1;
            if (tok >= 0 && tok < V && tok != mtp[0]) {
                int dup = 0;
                for (int j = 0; j < nh; j++) if (histp[j] == tok) { dup = 1; break; }
                if (!dup) histp[nh++] = tok;
            }
            tok = b - 1;
            if (tok >= 0 && tok < V && tok != mtp[0]) {
                int dup = 0;
                for (int j = 0; j < nh; j++) if (histp[j] == tok) { dup = 1; break; }
                if (!dup) histp[nh++] = tok;
            }
        }
    }
    if (nh > 1) {
        for (int i = 0; i < nh; i++) {
            int best = i;
            for (int j = i + 1; j < nh; j++)
                if (logits[histp[j]] > logits[histp[best]]) best = j;
            if (best != i) {
                int tmp = histp[i];
                histp[i] = histp[best];
                histp[best] = tmp;
            }
        }
    }
    int wfound = 0;
    int mtp_floor = 1;
    if (want >= 2 && nm >= 2) mtp_floor = 2;
    if (want >= 4 && nm >= 3) mtp_floor = 3;
    if (q35_g_d1_miss_streak > 0 && want >= 3 && nm >= 3) mtp_floor = 3;
    if (mtp_floor > nm) mtp_floor = nm;
    if (mtp_floor > want) mtp_floor = want;
    for (int i = 0; i < mtp_floor; i++) {
        cand[wfound] = mtp[i];
        clog[wfound] = mlg[i];
        wfound++;
    }
    int hi = 0, mi = mtp_floor;
    float hb = q35_g_hist_bias;
    if (hb < 0.25f) hb = 0.25f;
    if (hb > 0.60f) hb = 0.60f;
    int rest = want - wfound;
    int hist_budget = (int)((float)rest * hb + 0.5f);
    if (rest >= 2 && hist_budget < 1) hist_budget = 1;
    if (q35_g_d1_miss_streak > 0 || q35_g_last_plen <= 1) {
        if (hist_budget < 1 && rest >= 1) hist_budget = 1;
        if (rest >= 3 && hist_budget < 2) hist_budget = 2;
    }
    if (hist_budget > nh) hist_budget = nh;
    if (hist_budget > rest) hist_budget = rest;
    if (hist_budget < 0) hist_budget = 0;
    while (wfound < want && (hi < hist_budget || mi < nm)) {
        int take_hist = 0;
        if (hi < hist_budget && mi < nm) {
            take_hist = (hi <= (mi - mtp_floor));
        } else if (hi < hist_budget) {
            take_hist = 1;
        }
        if (take_hist) {
            int tok = histp[hi++];
            int dup = 0;
            for (int j = 0; j < wfound; j++) if (cand[j] == tok) { dup = 1; break; }
            if (dup) continue;
            cand[wfound] = tok;
            clog[wfound] = logits[tok];
            wfound++;
            q35_g_res_reserve++;
            continue;
        }
        if (mi < nm) {
            int tok = mtp[mi++];
            int dup = 0;
            for (int j = 0; j < wfound; j++) if (cand[j] == tok) { dup = 1; break; }
            if (dup) continue;
            cand[wfound] = tok;
            clog[wfound] = logits[tok];
            wfound++;
            continue;
        }
        break;
    }
    if (wfound < want) {
        wfound = q35_draft_reserve_d1(cand, clog, wfound, want, logits, V, hist, hlen, ngram_order);
    }
    for (int i = 0; i < mtp_floor && i < nm; i++) {
        int tok = mtp[i];
        int has = 0;
        for (int j = 0; j < wfound; j++) if (cand[j] == tok) { has = 1; break; }
        if (has) continue;
        if (wfound < want) {
            cand[wfound] = tok;
            clog[wfound] = mlg[i];
            wfound++;
        } else if (wfound > mtp_floor) {
            int worst = mtp_floor;
            for (int j = mtp_floor + 1; j < wfound; j++)
                if (clog[j] < clog[worst]) worst = j;
            cand[worst] = tok;
            clog[worst] = mlg[i];
        }
    }
    return wfound;
}

static int q35_pick_draft_V(int V) {
    if (V <= 0) return V;
    int draft_V = V;
    const char* env_dv = getenv("STRATUM_DRAFT_VOCAB");
    if (env_dv) {
        int want = atoi(env_dv);
        if (want > 0 && want < V) draft_V = want;
    } else if (q35_g_draft_adapt_V > 0 && q35_g_draft_adapt_V < V) {
        draft_V = q35_g_draft_adapt_V;
    }
    int force_full = 0;
    const char* ef = getenv("STRATUM_DRAFT_FULL");
    if (ef && atoi(ef) != 0) force_full = 1;
    size_t ms = g_st.mmap_size ? g_st.mmap_size : 0;
    size_t mres = q35_model_resident_bytes();
    if (mres > ms && ms > 0) mres = ms;
    double rf = (ms > 0) ? ((double)mres / (double)ms) : 0.0;
    int soft_thrash = q35_runtime_thrash()
        || (q35_g_soft_warm && rf < 0.55)
        || (q35_g_soft_warm && q35_g_soft_prefix_end > 0
            && q35_g_soft.hot_end + (size_t)(1024ULL << 20) < q35_g_soft_prefix_end
            && rf < 0.70);
    if (!force_full && q35_g_draft_full_auto && !soft_thrash) force_full = 1;
    if (!force_full) {
        if (!soft_thrash && q35_g_soft_warm && ms > 0 && mres >= (size_t)((ms * 72) / 100)
            && (q35_g_last_main_s <= 0.0 || q35_g_last_main_s < 2.70))
            force_full = 1;
        if (!soft_thrash && ms > 0 && mres >= (size_t)((ms * 78) / 100)
            && (q35_g_last_main_s <= 0.0 || q35_g_last_main_s < 2.80))
            force_full = 1;
    }
    if (force_full) {
        draft_V = V;
        q35_g_draft_full_uses++;
    } else if (env_dv == NULL && (q35_g_draft_adapt_V <= 0 || soft_thrash)) {
        int cap = 98304;
        if (soft_thrash && q35_g_d1_miss_streak >= 2) cap = 163840;
        else if (soft_thrash && q35_g_last_plen <= 1) cap = 131072;
        else if (soft_thrash && q35_g_last_main_s > 3.40) cap = 98304;
        else if (soft_thrash && q35_g_last_main_s > 2.90) cap = 114688;
        else if (soft_thrash) cap = 131072;
        else if (rf >= 0.55) cap = 163840;
        if (cap > V) cap = V;
        if (draft_V > cap) draft_V = cap;
        if (soft_thrash && draft_V < 98304) draft_V = 98304;
        if (soft_thrash && q35_g_d1_miss_streak >= 2 && draft_V < 131072) {
            draft_V = 131072;
            if (draft_V > V) draft_V = V;
        }
    }
    if (draft_V < 4096) draft_V = 4096;
    if (draft_V > V) draft_V = V;
    return draft_V;
}


static void q35_policy_pick_topo(Q35ScenePolicy* p, float entropy, float pmax,
                                 int rem_tok, int slots_left, int maxw_cfg,
                                 int* want_d1, int* d2_mode, int* d2_per,
                                 int* force_chain_d2, int* step_B_io) {
    if (!p || !want_d1 || !d2_mode || !d2_per || !force_chain_d2) return;
    int step_B = step_B_io ? *step_B_io : p->tree_B;
    if (slots_left < 0) slots_left = 0;
    int wd1 = maxw_cfg;
    int d2m = 0, d2p = 0, fcd2 = 0;
    int topo = Q35_TOPO_WIDE;

    if (!p->policy_on) {
        if (p->branch_depth >= 2) {
            if (p->tree_B >= 10) { wd1 = 3; d2m = 2; d2p = 2; }
            else { wd1 = 4; d2m = 1; d2p = 1; }
            if (wd1 > maxw_cfg) wd1 = maxw_cfg;
        } else {
            wd1 = slots_left;
            if (wd1 > maxw_cfg) wd1 = maxw_cfg;
            if (p->chain_d2 && slots_left >= 3 && wd1 >= 2) {
                wd1 = slots_left - 1;
                if (wd1 > maxw_cfg) wd1 = maxw_cfg;
                fcd2 = 1; d2m = 1; d2p = 1;
            }
        }
        if (wd1 < 1) wd1 = 1;
        if (wd1 > slots_left) wd1 = slots_left;
        *want_d1 = wd1; *d2_mode = d2m; *d2_per = d2p; *force_chain_d2 = fcd2;
        return;
    }

    float H = entropy;
    if (p->steps > 0) H = 0.65f * p->entropy_ema + 0.35f * entropy;
    float aema = p->accept_ema;
    int thrash = (p->scene == Q35_SCENE_THRASH);

    if (pmax >= 0.72f || H <= 0.55f) {
        topo = thrash ? Q35_TOPO_BAL : Q35_TOPO_DEEP;
    } else if (pmax >= 0.45f || H <= 1.15f) {
        topo = thrash ? Q35_TOPO_BAL : Q35_TOPO_CHAIN;
    } else if (aema >= 2.35f && !thrash) {
        topo = Q35_TOPO_DEEP;
    } else {
        topo = thrash ? Q35_TOPO_WIDE : Q35_TOPO_WIDE;
    }

    if (rem_tok <= 1) topo = Q35_TOPO_WIDE;
    /* thrash: always keep top-2 d1 cover; chain only after d1 slots reserved */
    if (thrash && rem_tok >= 2 && slots_left >= 2)
        topo = Q35_TOPO_BAL;
    else if (thrash && rem_tok >= 2)
        topo = Q35_TOPO_CHAIN;

    switch (topo) {
    case Q35_TOPO_CHAIN:
        wd1 = 2;
        if (pmax >= 0.92f && !thrash) wd1 = 1;
        if (wd1 > maxw_cfg) wd1 = maxw_cfg;
        if (wd1 > slots_left) wd1 = slots_left;
        if (slots_left >= 2) {
            fcd2 = 1; d2m = 1; d2p = 1;
            if (wd1 > slots_left - 1 && slots_left > 1) wd1 = slots_left - 1;
            if (wd1 < 1) wd1 = 1;
            if (thrash && wd1 < 2 && slots_left >= 3) wd1 = 2;
        }
        if (aema >= 2.2f && slots_left >= 3 && !thrash) {
            d2p = 2; d2m = 2;
        }
        break;
    case Q35_TOPO_BAL:
        /* thrash: top-2 d1; if B>=5 give each a d2 child (spread), else one d2 under best */
        wd1 = thrash ? 2 : 3;
        if (wd1 > maxw_cfg) wd1 = maxw_cfg;
        if (wd1 > slots_left) wd1 = slots_left;
        if (thrash && slots_left >= 4 && wd1 >= 2) {
            fcd2 = 0; d2m = 0; d2p = 1;
            if (wd1 > 2) wd1 = 2;
            if (wd1 > slots_left - 2) wd1 = slots_left - 2;
            if (wd1 < 2) wd1 = 2;
        } else if (slots_left >= wd1 + 1 && wd1 >= 1) {
            fcd2 = 1; d2m = 1; d2p = 1;
            if (wd1 > slots_left - 1) wd1 = slots_left - 1;
        } else if (thrash && slots_left >= 2) {
            wd1 = slots_left;
            if (wd1 > maxw_cfg) wd1 = maxw_cfg;
            fcd2 = 0; d2m = 0; d2p = 0;
        }
        if (thrash && wd1 < 2 && slots_left >= 2) {
            wd1 = 2;
            if (wd1 > maxw_cfg) wd1 = maxw_cfg;
            if (wd1 > slots_left) wd1 = slots_left;
        }
        break;
    case Q35_TOPO_DEEP:
        wd1 = thrash ? 2 : 3;
        if (wd1 > maxw_cfg) wd1 = maxw_cfg;
        if (wd1 > slots_left) wd1 = slots_left;
        if (slots_left >= 2) {
            fcd2 = 1; d2m = (p->tree_B >= 8) ? 2 : 1; d2p = (p->tree_B >= 8) ? 2 : 1;
            if (wd1 > slots_left - 1 && slots_left > 1) wd1 = slots_left - 1;
        }
        if (!thrash && step_B < p->tree_B && aema >= 2.4f && rem_tok > 3)
            step_B = p->tree_B;
        break;
    case Q35_TOPO_WIDE:
    default:
        wd1 = slots_left;
        if (wd1 > maxw_cfg) wd1 = maxw_cfg;
        if (wd1 > 8) wd1 = 8;
        if (p->chain_d2 && slots_left >= 3 && wd1 >= 2) {
            wd1 = slots_left - 1;
            if (wd1 > maxw_cfg) wd1 = maxw_cfg;
            if (thrash) {
                wd1 = 2;
                if (wd1 > maxw_cfg) wd1 = maxw_cfg;
                if (wd1 > slots_left - 1) wd1 = slots_left - 1;
            }
            if (wd1 < 1) wd1 = 1;
            fcd2 = 1; d2m = 1; d2p = 1;
        } else {
            fcd2 = 0; d2m = 0; d2p = 0;
            if (thrash && wd1 < 2 && slots_left >= 2) {
                wd1 = 2;
                if (wd1 > maxw_cfg) wd1 = maxw_cfg;
            }
        }
        break;
    }

    if (p->branch_depth >= 2 && topo != Q35_TOPO_WIDE) {
        if (d2m == 0) { d2m = 1; d2p = 1; }
    }

    if (wd1 < 1) wd1 = 1;
    if (thrash && slots_left >= 2 && wd1 < 2) wd1 = 2;
    if (wd1 > slots_left) wd1 = slots_left;
    if (step_B < 1) step_B = 1;
    if (thrash && rem_tok >= 2) {
        if (topo == Q35_TOPO_WIDE) topo = Q35_TOPO_BAL;
        if (step_B_io && *step_B_io < 5 && rem_tok >= 3)
            *step_B_io = 5;
        if (step_B_io && *step_B_io > step_B) step_B = *step_B_io;
        if (wd1 < 2 && slots_left >= 2) wd1 = 2;
        if (wd1 > maxw_cfg) wd1 = maxw_cfg;
        if (slots_left >= 4 && wd1 >= 2) {
            fcd2 = 0;
            d2m = 0;
            d2p = 1;
            wd1 = 2;
            if (wd1 > maxw_cfg) wd1 = maxw_cfg;
            if (wd1 > slots_left - 2) wd1 = slots_left - 2;
            if (wd1 < 2 && slots_left >= 2) wd1 = 2;
        } else if (slots_left >= wd1 + 2 && wd1 >= 2) {
            fcd2 = 0;
            d2m = 0;
            d2p = 1;
            if (wd1 > slots_left - wd1) wd1 = slots_left / 2;
            if (wd1 < 2) wd1 = 2;
            if (wd1 > maxw_cfg) wd1 = maxw_cfg;
        } else if (slots_left >= wd1 + 1 && wd1 >= 1) {
            fcd2 = 1;
            d2m = 1;
            d2p = 1;
            if (wd1 > slots_left - 1) wd1 = slots_left - 1;
            if (wd1 < 1) wd1 = 1;
        } else {
            fcd2 = 0;
            d2m = 0;
            d2p = 0;
        }
        if (wd1 < 1) wd1 = 1;
        if (wd1 > slots_left) wd1 = slots_left;
    }
    p->topo = topo;
    *want_d1 = wd1;
    if (q35_g_soft_warm) {
        int soft_hot = q35_soft_mostly_hot();
        int full_hot = stratum_soft_is_full_hot(&q35_g_soft);
        int slow = (q35_g_last_main_s > 0.0 && q35_g_last_main_s > 2.95);
        if (soft_hot || p->accept_ema >= 2.1f || slow
            || thrash || q35_g_stage_sticky || q35_g_last_main_s > 2.80)
            topo = Q35_TOPO_CHAIN;
        else if (p->accept_ema >= 1.5f) topo = Q35_TOPO_BAL;
        else topo = Q35_TOPO_WIDE;
        fcd2 = 1; d2m = 1; d2p = 1;
        if (slow) {
            if (wd1 > 2) wd1 = 2;
            fcd2 = 1; d2m = 1; d2p = 1;
            if (step_B_io && *step_B_io < 4) *step_B_io = 4;
        } else if (full_hot && p->accept_ema >= 2.0f) {
            if (wd1 > 3) wd1 = 3;
            fcd2 = 1; d2m = 1; d2p = 1;
            if (step_B_io && *step_B_io < 5) *step_B_io = 5;
            if (p->accept_ema >= 2.5f && step_B_io && *step_B_io < 6)
                *step_B_io = 6;
        } else if ((q35_g_frontier_advances > 0 || soft_hot) && p->accept_ema >= 1.9f) {
            if (wd1 > 2) wd1 = 2;
            fcd2 = 1; d2m = 1; d2p = 1;
            if (step_B_io && *step_B_io < (soft_hot ? 5 : 4))
                *step_B_io = soft_hot ? 5 : 4;
        }
        if (!full_hot && wd1 > 2) wd1 = 2;
        if (full_hot && wd1 > 3) wd1 = 3;
        if (wd1 < 1) wd1 = 1;
        *want_d1 = wd1;
        p->topo = topo;
    }
    *d2_mode = d2m;
    *d2_per = d2p;
    *force_chain_d2 = fcd2;
    if (step_B_io) *step_B_io = step_B;
}

static void q35_policy_update(Q35ScenePolicy* p, float entropy, int n_emit, int mains) {
    if (!p) return;
    if (mains < 1) mains = 1;
    float tpm = (float)n_emit / (float)mains;
    if (p->steps == 0) {
        p->accept_ema = tpm;
        p->entropy_ema = entropy;
    } else {
        p->accept_ema = 0.70f * p->accept_ema + 0.30f * tpm;
        p->entropy_ema = 0.70f * p->entropy_ema + 0.30f * entropy;
    }
    p->steps++;
    if ((p->steps % 4) == 0) p->scene = q35_detect_scene();
    if (p->scene == Q35_SCENE_THRASH) {
        size_t fr = q35_free_reclaim_bytes();
        size_t ms = g_st.mmap_size ? g_st.mmap_size : 0;
        int deep = (ms > 0 && fr < (size_t)((ms * 50) / 100));
        int mild = (ms > 0 && fr >= (size_t)((ms * 70) / 100));
        int scan_hot = (q35_g_last_main_s > 0.0 && q35_g_last_main_s < 3.60);
        if (q35_g_soft_warm || scan_hot || p->steps >= 1
            || (!deep && (mild || p->accept_ema >= 1.8f))) p->extend = 1;
        else if (deep && !q35_g_soft_warm && !scan_hot) p->extend = 0;
        if (p->policy_on) {
            if (q35_g_soft_warm && p->accept_ema >= 2.2f && p->maxw > 2) p->maxw = 2;
            if (n_emit <= 1 && p->maxw < p->tree_B - 1) p->maxw++;
            else if (n_emit >= 3 && p->maxw > 2) p->maxw--;
            if ((mild || q35_g_soft_warm || scan_hot) && p->extend_k < 3) p->extend_k = 3;
            if ((q35_g_soft_warm || scan_hot) && p->extend_k < 4) p->extend_k = 4;
        }
    } else if (p->policy_on) {
        if (p->accept_ema >= 1.9f) p->extend = 1;
        else if (p->accept_ema < 1.7f) p->extend = 0;
        if (n_emit <= 1 && p->maxw < 6) p->maxw++;
        else if (n_emit >= p->tree_B - 1 && p->maxw > 2) p->maxw--;
    }
}


static int*   q35_g_full_attn_slot = NULL;
static int    q35_g_n_full_attn    = 0;

static float* q35_g_ssm_conv_state = NULL;
static uint16_t* q35_g_ssm_rec_state = NULL;
static int*   q35_g_ssm_layer_slot = NULL;
static int    q35_g_n_ssm_layers   = 0;

static void q35_embed_lookup(int token_id, float* out);
static int  q35_forward_mtp(const float* main_hidden, int prev_token, int position);

