static int q35_runtime_thrash(void) {
    if (stratum_soft_is_full_hot(&q35_g_soft)) return 0;
    if (stratum_soft_is_thrash(&q35_g_soft)) return 1;
    if (q35_g_soft_warm) {
        if (q35_g_last_main_s > 0.0 && q35_g_last_main_s > 2.55
            && !q35_soft_mostly_hot())
            return 1;
        return 0;
    }
    if (q35_g_last_main_s > 0.0 && q35_g_last_main_s > 2.55) return 1;
    if (stratum_soft_io_pressure(&q35_g_soft)) return 1;
    return 0;
}

static void q35_stage_sticky_update(void) {
    if (stratum_soft_is_full_hot(&q35_g_soft)) {
        q35_g_stage_sticky = 0;
        return;
    }
    size_t ms = g_st.mmap_size ? g_st.mmap_size : 0;
    size_t mres = q35_model_resident_bytes();
    if (mres > ms && ms > 0) mres = ms;
    double rf = (ms > 0) ? ((double)mres / (double)ms) : 0.0;
    if (rf >= 0.85 || q35_soft_mostly_hot()) {
        q35_g_stage_sticky = 0;
        return;
    }
    if (rf < 0.55 && !q35_g_soft_warm) {
        q35_g_stage_sticky = 1;
        return;
    }
    if (q35_g_last_main_s > 2.55 && q35_runtime_thrash() && rf < 0.80) {
        q35_g_stage_sticky = 1;
        return;
    }
    if (q35_g_last_main_s > 2.80 && rf < 0.65) {
        q35_g_stage_sticky = 1;
        return;
    }
    if (q35_g_soft_warm && q35_g_last_main_s > 3.00 && rf < 0.75) {
        q35_g_stage_sticky = 1;
        return;
    }
    if (q35_g_stage_sticky) {
        if (rf >= 0.65) q35_g_stage_sticky = 0;
        else if (q35_g_last_main_s > 0.0 && q35_g_last_main_s < 2.25)
            q35_g_stage_sticky = 0;
        else if (q35_g_last_main_s > 0.0 && q35_g_last_main_s < 2.55
                 && !q35_runtime_thrash())
            q35_g_stage_sticky = 0;
    }
}

static int q35_want_stage_force(void) {
    if (stratum_soft_is_full_hot(&q35_g_soft)) return 0;
    if (q35_soft_mostly_hot()) return 0;
    if (!q35_g_stage_sticky) {
        if (!(q35_runtime_thrash() && q35_g_last_main_s > 2.90))
            return 0;
    } else if (q35_g_last_main_s > 0.0 && q35_g_last_main_s < 2.70) {
        return 0;
    }
    static double cache_t = 0.0;
    static double cache_rf = 0.0;
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    double t = now.tv_sec + now.tv_nsec / 1e9;
    if (cache_t <= 0.0 || (t - cache_t) > 0.08) {
        size_t ms = g_st.mmap_size ? g_st.mmap_size : 0;
        size_t mres = q35_model_resident_bytes();
        if (mres > ms && ms > 0) mres = ms;
        cache_rf = (ms > 0) ? ((double)mres / (double)ms) : 0.0;
        cache_t = t;
    }
    if (cache_rf >= 0.82) return 0;
    if (cache_rf >= 0.68 && q35_g_last_main_s > 0.0 && q35_g_last_main_s < 2.70)
        return 0;
    if (cache_rf >= 0.60 && q35_g_last_main_s > 0.0 && q35_g_last_main_s < 2.50)
        return 0;
    if (q35_g_stage_sticky && cache_rf < 0.78
        && (q35_g_last_main_s <= 0.0 || q35_g_last_main_s > 2.45))
        return 1;
    if (q35_g_soft_warm && q35_g_last_main_s > 2.95 && cache_rf < 0.75)
        return 1;
    if (q35_runtime_thrash() && q35_g_last_main_s > 2.75 && cache_rf < 0.65)
        return 1;
    if (!q35_g_soft_warm && q35_runtime_thrash()
        && (q35_g_last_main_s <= 0.0 || q35_g_last_main_s > 2.60)
        && cache_rf < 0.62)
        return 1;
    return 0;
}

static int q35_soft_mostly_hot(void) {
    static int cached = 0;
    static double cached_t = 0.0;
    static int cached_scans = -1;
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    double t = now.tv_sec + now.tv_nsec / 1e9;
    if (cached_t > 0.0 && (t - cached_t) < 0.045
        && cached_scans == q35_g_main_scans
        && !(q35_g_last_main_s > 2.95))
        return cached;
    if (q35_g_last_main_s > 2.95 || stratum_soft_io_pressure(&q35_g_soft)) {
        cached = 0; cached_t = t; cached_scans = q35_g_main_scans;
        return 0;
    }
    q35_soft_io_sync();
    cached = stratum_soft_mostly_hot(&q35_g_soft);
    cached_t = t;
    cached_scans = q35_g_main_scans;
    return cached;
}

