static int q35_wt_next_free_slots(void) {
    q35_wt_next_try_harvest();
    int n = 0;
    for (int s = 0; s < q35_WT_NEXT_N; s++)
        if (!q35_g_wt_next_busy[s] && q35_g_wt_next_w[s] == NULL) n++;
    return n;
}

